package lk.gov.health.govcare.ai;
import lk.gov.health.govcare.security.*; import org.springframework.web.bind.annotation.*; import java.util.*; import static lk.gov.health.govcare.ai.AIIntelligenceDtos.*;
@RestController @RequestMapping("/api/ai") public class AIIntelligenceController { private final AIIntelligenceService service; private final CurrentUser current; public AIIntelligenceController(AIIntelligenceService s,CurrentUser c){service=s;current=c;} @PostMapping("/predict/{module}") public Map<String,Object> predict(@PathVariable String module,@RequestBody PredictionRequest q){return service.predict(current.get(),module,q);} @GetMapping("/history/{patientId}") public Map<String,Object> history(@PathVariable String patientId){return service.history(current.get(),patientId);} @GetMapping("/dashboard") public Map<String,Object> dashboard(){return service.dashboard(current.get());} }
